from collections import deque

class Node:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
    def __repr__(self):
        return f"Node({self.val!r})"

def build(values):
    """Build a tree from a level-order list with None gaps."""
    if not values or values[0] is None:
        return None
    it = iter(values)
    root = Node(next(it))
    q = deque([root])
    while q:
        node = q.popleft()
        for side in ("left", "right"):
            try:
                v = next(it)
            except StopIteration:
                return root
            if v is not None:
                child = Node(v)
                setattr(node, side, child)
                q.append(child)
    return root

def to_list(root):
    """The level-order list with None gaps, trailing Nones dropped."""
    out, q = [], deque([root])
    while q:
        node = q.popleft()
        if node is None:
            out.append(None)
            continue
        out.append(node.val)
        q.append(node.left)
        q.append(node.right)
    while out and out[-1] is None:
        out.pop()
    return out

def balanced(values):
    if not values:
        return None
    m = len(values) // 2
    return Node(values[m], balanced(values[:m]), balanced(values[m + 1:]))

class _Seen(Node):
    """A node that records every read of val, left or right."""
    seen = set()

    def __init__(self, val, left=None, right=None):
        self.__dict__.update(_v=val, _l=left, _r=right)

    def __getattr__(self, name):
        key = {"val": "_v", "left": "_l", "right": "_r"}.get(name)
        if key is None:
            raise AttributeError(name)
        _Seen.seen.add(id(self))
        return self.__dict__[key]

def _copy(node):
    if node is None:
        return None
    return _Seen(node.val, _copy(node.left), _copy(node.right))

def touched(root, k):
    """How many nodes kth_smallest reads."""
    t = _copy(root)
    _Seen.seen = set()
    kth_smallest(t, k)
    return len(_Seen.seen)

