import heapq


def merge_k(lists):
    heap = []
    for i, xs in enumerate(lists):
        if xs:
            heapq.heappush(heap, (xs[0], i, 0))
    out = []
    while heap:
        value, i, j = heapq.heappop(heap)
        out.append(value)
        if j + 1 < len(lists[i]):
            heapq.heappush(heap, (lists[i][j + 1], i, j + 1))
    return out

import heapq


def running_median(xs):
    lo, hi = [], []      # lo: max-heap of the smaller half (negated); hi: min-heap of the larger half
    out = []
    for x in xs:
        if lo and x > -lo[0]:
            heapq.heappush(hi, x)
        else:
            heapq.heappush(lo, -x)
        if len(lo) > len(hi) + 1:
            heapq.heappush(hi, -heapq.heappop(lo))
        elif len(hi) > len(lo):
            heapq.heappush(lo, -heapq.heappop(hi))
        if len(lo) > len(hi):
            out.append(float(-lo[0]))
        else:
            out.append((-lo[0] + hi[0]) / 2)
    return out
